class Solution {
public:
    int dominantIndex(vector<int>& nums) {
        int largest = -1, second = -1, index = -1;
        for (int i = 0; i < (int)nums.size(); ++i) {
            if (nums[i] > largest) {
                second = largest;
                largest = nums[i];
                index = i;
            } else second = max(second, nums[i]);
        }
        return largest >= 2LL * second ? index : -1;
    }
};
